@Composable
fun TokoTheme(gelap: Boolean = isSystemInDarkTheme(), content: @Composable () -> Unit) {
    val ctx = LocalContext.current
    val skema = when {
        Build.VERSION.SDK_INT >= Build.VERSION_CODES.S -> if (gelap) dynamicDarkColorScheme(ctx) else dynamicLightColorScheme(ctx)
        gelap -> darkColorScheme(primary = Color(0xFFE6B89C))
        else -> lightColorScheme(primary = Color(0xFF6B3E26))
    }
    MaterialTheme(colorScheme = skema, typography = TokoTypography, content = content)
}

@Composable
fun BadgeKeranjang(jumlah: Int) {
    AnimatedContent(
        targetState = jumlah,
        transitionSpec = { (slideInVertically { -it } + fadeIn()) togetherWith (slideOutVertically { it } + fadeOut()) },
        label = "jumlah",
    ) { n -> Text("$n", style = MaterialTheme.typography.labelLarge) }
}

@Composable
fun LayarCheckout(vm: CheckoutViewModel, snackbar: SnackbarHostState) {
    LaunchedEffect(Unit) {
        vm.event.collect { e ->
            when (e) {
                is CheckoutEvent.Sukses -> snackbar.showSnackbar("Pesanan ${e.nomor} dibuat")
                is CheckoutEvent.Gagal -> snackbar.showSnackbar(e.pesan, actionLabel = "Coba lagi")
            }
        }
    }
    val scope = rememberCoroutineScope()
    Button(onClick = { scope.launch { vm.bayar() } }) { Text("Bayar sekarang") }
}

@Entity(tableName = "catatan")
data class Catatan(
    @PrimaryKey(autoGenerate = true) val id: Long = 0,
    val judul: String,
    val isi: String,
    val diubah: Long = System.currentTimeMillis(),
)

@Dao
interface CatatanDao {
    @Query("SELECT * FROM catatan ORDER BY diubah DESC")
    fun semua(): Flow<List<Catatan>>

    @Upsert
    suspend fun simpan(c: Catatan)

    @Delete
    suspend fun hapus(c: Catatan)
}

