class PemilihQtyTest {
    @get:Rule val rule = createComposeRule()

    @Test
    fun tombolTambahNonaktifDiMaks() {
        rule.setContent { var q by remember { mutableIntStateOf(2) }; PemilihQty(q, { q = it }, maks = 3) }
        rule.onNodeWithContentDescription("Tambah").performClick()
        rule.onNodeWithText("3").assertIsDisplayed()
        rule.onNodeWithContentDescription("Tambah").assertIsNotEnabled()
    }
}

class EditorViewModel(private val dao: CatatanDao, id: Long) : ViewModel() {
    private val teks = MutableStateFlow("")
    init {
        viewModelScope.launch {
            teks.drop(1).debounce(600).distinctUntilChanged().collect { isi ->
                dao.simpan(Catatan(id = id, judul = isi.lineSequence().first().take(40), isi = isi))
            }
        }
    }
    fun ketik(isi: String) { teks.value = isi }
}

