function specificity(sel) {
  const s = sel.replace(/:not\(([^)]*)\)/g, " $1 ");       // :not() dihitung dari isinya
  const a = (s.match(/#[\w-]+/g) || []).length;
  const b = (s.match(/\.[\w-]+|\[[^\]]+\]|(?<!:):(?!:)[\w-]+/g) || []).length;
  const c = (s.replace(/#[\w-]+|\.[\w-]+|\[[^\]]+\]|:{1,2}[\w-]+/g, " ").match(/(^|[\s>+~])[a-z][\w-]*/gi) || []).length
          + (s.match(/::[\w-]+/g) || []).length;
  return [a, b, c];
}
