for (const [fg, bg, ket] of pasang) {
  const r = kontras(fg, bg);
  console.log(`${ket.padEnd(28)} ${r.toFixed(2)}:1  ${r >= 4.5 ? "lulus AA" : r >= 3 ? "hanya teks besar" : "GAGAL"}`);
}

