  let jumlah = 0, potongan = 0, maksMs = 0;
  for (let i = 0; i < arr.length; i += ukuranPotong) {
    const t0 = performance.now();
    for (let j = i; j < Math.min(i + ukuranPotong, arr.length); j++) jumlah += Math.sqrt(arr[j]);
