function bubble(a) {
  a = [...a]; let tukar = true, putaran = 0;
  while (tukar) { tukar = false; putaran++;
    for (let i = 0; i < a.length - putaran; i++) if (a[i] > a[i + 1]) { [a[i], a[i + 1]] = [a[i + 1], a[i]]; tukar = true; } }
  return [a, putaran];
}
