function prima(n) {
  const coret = new Uint8Array(n + 1);
  for (let i = 2; i * i <= n; i++) if (!coret[i]) for (let j = i * i; j <= n; j += i) coret[j] = 1;
  const hasil = []; for (let i = 2; i <= n; i++) if (!coret[i]) hasil.push(i);
  return hasil;
}
