            byte[] b = "{\"status\":\"UP\"}".getBytes();
            ex.getResponseHeaders().add("Content-Type", "application/json");
            ex.sendResponseHeaders(200, b.length);
            ex.getResponseBody().write(b);
            ex.close();
        });
        s.start();
        var klien = HttpClient.newHttpClient();
        var res = klien.send(HttpRequest.newBuilder(URI.create("http://localhost:" + s.getAddress().getPort() + "/health")).build(), HttpResponse.BodyHandlers.ofString());
        System.out.println(res.statusCode() + " " + res.body());
        s.stop(0);
    }
}

