import functools

def retry(kali):
    def dekor(f):
        @functools.wraps(f)
        def bungkus(*a, **k):
            for i in range(1, kali + 1):
                try: return f(*a, **k)
                except ConnectionError as e: print(f"  percobaan {i} gagal: {e}")
            raise ConnectionError("menyerah")
        return bungkus
    return dekor

def butuh_peran(peran):
    def dekor(f):
        @functools.wraps(f)
        def bungkus(user, *a):
            if peran not in user["peran"]: return f"403: {user['nama']} bukan {peran}"
            return f(user, *a)
        return bungkus
    return dekor

