def postfix(ekspr):                     # "3 4 + 2 *" = (3 + 4) * 2
    st = []
    for tok in ekspr.split():
        if tok in "+-*/":
            b, a = st.pop(), st.pop()
            st.append({"+": a + b, "-": a - b, "*": a * b, "/": a / b}[tok])
        else: st.append(float(tok))
    return st.pop()
print("3 4 + 2 * =", postfix("3 4 + 2 *"), "| 5 1 2 + 4 * + 3 - =", postfix("5 1 2 + 4 * + 3 -"))

