import random
class N:
    __slots__ = ("k", "l", "r")
    def __init__(self, k): self.k, self.l, self.r = k, None, None

def sisip(akar, k):
    if akar is None: return N(k)
    n = akar
    while True:
        arah = "l" if k < n.k else "r"
        anak = getattr(n, arah)
        if anak is None: setattr(n, arah, N(k)); return akar
        n = anak

def tinggi(n):
    t, tumpuk = 0, [(n, 1)]
    while tumpuk:
        x, d = tumpuk.pop()
        if x: t = max(t, d); tumpuk += [(x.l, d + 1), (x.r, d + 1)]
    return t

