  katalog.filter((p) => p.nama.toLowerCase().includes(q.toLowerCase()) && (!kat || p.kategori === kat));
const urut = (d: Produk[], by: "termurah" | "termahal") => [...d].sort((a, b) => (by === "termurah" ? a.harga - b.harga : b.harga - a.harga));

type Item = Produk & { qty: number };
