function format(nilai: number | Date): string {
  if (typeof nilai === "number") return nilai.toLocaleString("id-ID");
  const p = (x: number) => String(x).padStart(2, "0");
  return `${p(nilai.getDate())}/${p(nilai.getMonth() + 1)}/${nilai.getFullYear()}`;
}

