function debounce<T extends unknown[]>(fn: (...a: T) => void, ms: number) {
  let t: ReturnType<typeof setTimeout> | undefined;
  return (...a: T) => { clearTimeout(t); t = setTimeout(() => fn(...a), ms); };
}
